  "prediction_basis_card_ids": ["C01", "C13", "C08", "C12"],
  "claims": [
    {
      "claim": "Human absolute-bioavailability records for phenolic/anilide drugs report F ≥ 60% (desvenlafaxine 80.5%, teriflunomide approaching 100%, proguanil up to 60%), supporting that the amide-phenol motif in the query can achieve F ≥ 20%.",
      "card_ids": ["C01", "C13", "C05"]
    },
    {
      "claim": "The lipophilic polyene zeaxanthin is reported to have high bioavailability in a lipid-rich matrix, indicating that high lipophilicity and poor aqueous solubility are not by themselves affirmative evidence of F < 20%.",
      "card_ids": ["C12"]
    },
    {
      "claim": "Apatinib, an oral anilide with good bioavailability in humans, provides additional support for the anilide scaffold being compatible with F ≥ 20%.",
      "card_ids": ["C08"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C01", "C02", "C03", "C04", "C05", "C06", "C07", "C08", "C09", "C10", "C11", "C12", "C13", "C14", "C15", "C16", "C17", "C18", "C19"]
    }
  ],
  "evidence_gaps": [
    "No direct fenretinide-specific absolute oral bioavailability measurement is present in the supplied records.",
    "No measured solubility/dissolution or first-pass metabolism data for the query; the logP-based solubility concern is a physicochemical prior, not endpoint evidence.",
    "Zeaxanthin's high bioavailability is tied to an egg-yolk lipid matrix and may not transfer to a standard oral formulation.",
    "Structural transfer from smaller, more polar high-F drugs (desvenlafaxine, teriflunomide) is limited by the query's much higher lipophilicity and molecular size."
  ],
  "decision_summary": "All L1 gold-voting records are directionally supportive of F ≥ 20%, with no affirmative threshold-relevant evidence for F < 20%. The query's high logP and unfavorable solubility prior raise absorption concerns, but the prior is mixed and generic solubility liabilities alone are insufficient to predict low. Therefore high is the better-supported prediction, with low confidence due to limited direct structural transferability."
}

